  //      mixer.clipAction(clips[0]).play();
  function buildClips(THREE) {
    return ANIMATIONS.map(function(anim) {
      var tracks = anim.tracks.map(function(t) {
        var trackName = t.bone + "." + t.type;
        if (t.type === "quaternion") {
          return new THREE.QuaternionKeyframeTrack(trackName, t.times, t.values);
        } else if (t.type === "position" || t.type === "scale") {
          return new THREE.VectorKeyframeTrack(trackName, t.times, t.values);
        } else {
          return new THREE.NumberKeyframeTrack(trackName, t.times, t.values);
        }
      });
      return new THREE.AnimationClip(anim.name, anim.duration, tracks);
    });
  }

  root.Idle_Animations = {
    animations: ANIMATIONS,
    buildClips: buildClips
  };
